using Vibe.Registry;
using Vibe.Registry.Remote;

namespace Vde.SecMan;

// SECMAN: serves HKLM\Security, generated by the plugins from what the system is really running. Refilled
// when their files change and every half minute (the kernel's switches cannot be watched), and served with
// fhived's protocol so each client is held to the permissions in the hive by its real uid.
public sealed class SecurityService : IDisposable
{
    public const string DefaultSocketPath = "/run/secman/security.sock";

    private readonly GeneratedHiveService _service;
    private readonly IReadOnlyList<ISecurityPlugin> _plugins;
    private readonly string _root;

    public SecurityService(IEnumerable<ISecurityPlugin>? plugins = null, string root = "/", Func<System.Net.Sockets.Socket, RegistryIdentity>? identityOf = null, TimeSpan? periodic = null)
    {
        _plugins = (plugins ?? SecurityBuilder.DefaultPlugins).ToList();
        _root = root;
        _service = new GeneratedHiveService("Security", hive => SecurityBuilder.Fill(hive, _plugins, _root), identityOf, periodic ?? TimeSpan.FromSeconds(30));
    }

    public Hive Hive => _service.Hive;
    public HiveServer Server => _service.Server;
    public void Refresh() => _service.Refresh();
    public void Watch() => _service.Watch(_plugins.SelectMany(p => p.WatchedFiles(_root)));
    public void Dispose() => _service.Dispose();
}
